PORTAL_JS = r"""
(()=>{
 const links=[...document.querySelectorAll('.sidebar nav a')];
 const activate=()=>links.forEach(a=>a.classList.toggle('active',a.hash===(location.hash||'#overview')));
 activate();addEventListener('hashchange',activate);
 const form=document.querySelector('form[action="/account/customize"]');
 if(form){const img=document.querySelector('#studio-image'),name=document.querySelector('#studio-name');
 const preview=()=>{const selected=form.querySelector('input[name="avatar_id"]:checked');if(selected)img.src='/account/portrait/'+encodeURIComponent(selected.value);name.textContent=form.elements.name.value||'Your citizen';};
 form.addEventListener('input',preview);form.addEventListener('reset',()=>setTimeout(preview,0));preview();}
 const chat=document.querySelector('.compose');if(chat)chat.addEventListener('submit',()=>{const b=chat.querySelector('button');b.disabled=true;b.textContent='Waiting for reply…';});
 let pending=false;
 const poll=async()=>{if(document.hidden||pending)return;pending=true;try{const r=await fetch('/account/status',{credentials:'same-origin',cache:'no-store'});if(r.status===401){document.querySelector('#live-status').textContent='Session expired · sign in again';return;}if(!r.ok)throw Error();const d=await r.json();document.querySelector('#live-status').textContent=d.status;let n=document.querySelector('#availability-note');if(!n){n=document.createElement('div');n.id='availability-note';n.className='connection-note';document.querySelector('.hero-copy').append(n);}n.textContent=d.joined?'Updated just now':d.accepting?'The world is open. Refresh to join.':d.loaded?'World loaded · new players are not being accepted yet.':'Waiting for the administrator to load a world.';if(d.accepting&&!document.querySelector('form[action="/account/join"]')&&!d.joined){const a=document.createElement('a');a.href='/account';a.className='quiet';a.textContent='World ready · refresh';n.append(' ',a);}}catch(e){document.querySelector('#live-status').textContent='Reconnecting…';}finally{pending=false;}};
 setInterval(poll,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
"""



def dashboard(user, world=None, entity=None, notice=''):
    ready = world is not None
    joined = entity is not None
    world_name = esc(world.shared_world.name) if ready else 'Shared world not set'
    name = esc(entity.name) if joined else esc(user['name'])
    state = esc(str(entity.metadata.get('state', 'Idle')).replace('_', ' ').title()) if joined else 'Waiting'
    action = world.actions.get(world.active_actions.get(str(entity.id), '')) if joined else None
    if action:
        state = esc(action.action_type.value.replace('_', ' ').title())
    status = ('Citizen active' if entity.active else 'Citizen inactive') if joined else ('Ready to join' if ready and world.shared_world.accepting_players else ('World closed to new players' if ready else 'Awaiting world'))
    if joined:
        cta = '<a class="primary" href="/game/">Enter the realm ↗</a>'
    elif ready and world.shared_world.accepting_players:
        cta = '<form method="post" action="/account/join"><button class="primary">Join this world →</button></form>'
    else:
        cta = '<a class="quiet" href="/account">Check availability</a>'
    from app.player_customization import form
    customization = form(entity) if joined else ''
    needs = ''
    if joined and entity.needs:
        for key in ('health', 'energy', 'hunger', 'thirst'):
            value = max(0, min(100, float(getattr(entity.needs, key))))
            needs += f'<div class="need"><label>{key.title()}<span>{value:.0f}/100</span></label><div class="track" role="meter" aria-label="{key}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{value}"><div class="fill" style="width:{value}%"></div></div></div>'
    episodes = sorted(world.episodes.get(str(entity.id), []), key=lambda e: e.importance, reverse=True)[:6] if joined else []
    memories = ''.join('<div class="memory"><p>'+esc(e.summary)+'</p></div>' for e in episodes)
    history = ''.join('<div class="message '+('user' if m.get('role') == 'user' else '')+'"><small>'+('You' if m.get('role') == 'user' else name)+'</small><p>'+esc(m.get('content', ''))+'</p></div>' for m in entity.metadata.get('player_chat', [])[-12:]) if joined else ''
    map_panel = '<iframe class="map" title="Citizen map and live needs" src="/account/view"></iframe><p class="footnote">Live local map · refreshes every 5 seconds · gold marks your citizen. Surface terrain is shown for all observation layers.</p>' if joined else '<div class="empty"><div class="symbol">◇</div><h2>'+('Your place in the realm' if ready else 'The realm is being prepared')+'</h2><p>'+esc(notice or ('Join to meet your citizen.' if ready and world.shared_world.accepting_players else 'The administrator will open the shared world here.'))+'</p>'+cta+'</div>'
    chat = '<div class="chat-log">'+(history or '<div class="empty">Start a conversation with '+name+'.</div>')+'</div><form class="compose" method="post" action="/account/chat"><label for="message">Message your citizen</label><textarea id="message" name="message" maxlength="1000" required placeholder="What did you discover today?"></textarea><button class="primary">Send message →</button></form><p class="footnote">Chat does not issue commands. Replies fall back to simulation status when the model is unavailable.</p>' if joined and entity.active else '<div class="empty">'+('This citizen is inactive.' if joined else 'Chat opens when you join the shared world.')+'</div>'
    metrics = [('World', world_name, 'One shared realm'), ('Citizen', name if joined else 'Not linked yet', status), ('Activity', state, 'Current recorded state'), ('Memories', str(len(episodes)) if joined else '—', 'Significant experiences')]
    portrait = '<img class="citizen-portrait" src="/account/portrait/'+esc(entity.avatar_id.value)+'" alt="'+name+'">' if joined else '<div class="waiting-orbit" aria-hidden="true"><span></span></div>'
    hero = '<section class="hero citizen-hero"><div class="portrait-stage">'+portrait+'<span class="stage-caption">'+('YOUR CITIZEN' if joined else 'YOUR NEXT CHAPTER')+'</span></div><div class="hero-copy"><span class="eyebrow">'+world_name+'</span><h1>'+name+'</h1><p class="muted">'+(state+' · '+esc(entity.gender.title())+' · '+esc(entity.diet.title()) if joined else 'Your citizen will join when the shared world opens.')+'</p><div class="world-status"><span id="live-status" class="badge '+('' if joined else 'waiting')+'" role="status">'+status+'</span>'+cta+'</div><a class="studio-link" href="#customize">'+('Edit appearance & name' if joined else 'Explore appearances')+' →</a></div></section>'
    if not joined:
        from app.player_customization import APPEARANCES
        customization = '<section class="panel" id="customize"><span class="eyebrow">Character studio</span><h2>Find your character</h2><p class="muted">Preview the available appearances. Saving opens after you join.</p><div class="looks">'+''.join('<div class="look"><img loading="lazy" src="/account/portrait/'+key+'" alt="'+label+'" width="70" height="90"><span>'+label+'</span></div>' for key,label in APPEARANCES)+'</div></section>'
    nonce = secrets.token_urlsafe(24)
    body = '<div class="shell"><aside class="sidebar"><a class="brand" href="/account"><b>AR.</b>AITIZEN REALM</a><nav aria-label="Dashboard"><a href="#overview">Overview</a><a href="#citizen">My citizen</a><a href="#customize">Customize</a><a href="#memories">Memories</a><a href="#conversation">Conversation</a></nav><div class="owner">Your citizen, their own story.<br>World settings are managed by the administrator.</div></aside><div class="content"><div class="top"><span>Player space / Overview</span><form method="post" action="/account/logout"><button class="quiet">Sign out</button></form></div><main id="overview" class="reveal">'+('<p role="status" class="badge">'+esc(notice)+'</p>' if notice else '')+hero+'<div class="metrics">'+''.join('<div class="metric"><small>'+k+'</small><strong>'+v+'</strong><span>'+sub+'</span></div>' for k,v,sub in metrics)+'</div><div class="columns"><div><section class="panel" id="citizen"><div class="panel-head"><div class="identity"><div class="avatar">'+esc((entity.name if joined else user['name'])[:1])+'</div><div><h2>'+('Your citizen' if joined else 'Shared world')+'</h2><span class="muted">'+name+'</span></div></div></div>'+map_panel+'</section>'+customization+'<section class="panel" id="memories"><h2>What stays with them</h2><p class="muted">Recorded experiences, ordered by importance</p>'+(memories or '<div class="empty">Discoveries and meaningful experiences will appear here.</div>')+'</section></div><div><section class="panel"><h2>At a glance</h2><p class="muted">'+state+'</p><div class="needs">'+needs+'</div><p class="footnote">'+('Hunger and thirst: lower is better. Snapshot at page load; live values appear on the map.' if joined else 'Needs appear when your citizen joins.')+'</p></section><section class="panel" id="conversation"><span class="eyebrow">Talk to your citizen</span><h2>A word with '+name+'</h2>'+chat+'</section></div></div></main></div></div>'
    script = PORTAL_JS + '''(()=>{try{if(sessionStorage.getItem('realm-dashboard-arrived'))return;}catch(e){}document.querySelector('.shell').inert=true;const cover=document.createElement('div');cover.className='arrival';cover.innerHTML='<iframe title="Animated realm arrival" src="/account/arrival"></iframe><button class="skip">Enter dashboard →</button>';document.body.append(cover);const button=cover.querySelector('button');button.focus();button.onclick=()=>{try{sessionStorage.setItem('realm-dashboard-arrived','1');}catch(e){}cover.classList.add('leaving');setTimeout(()=>{cover.remove();document.querySelector('.shell').inert=false;document.querySelector('h1').tabIndex=-1;document.querySelector('h1').focus();},600);};})();'''
    return HTMLResponse('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your citizen · Aitizen Realm</title><style>'+CSS+'</style><body>'+body+'<script nonce="'+nonce+'">'+script+'</script></body></html>',headers={'Cache-Control':'no-store','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-"+nonce+"'; connect-src 'self'; img-src 'self'; frame-src 'self'; form-action 'self'; frame-ancestors 'self'",'Referrer-Policy':'same-origin'})


async def arrival(request):
    from app.player_accounts import identity
    if not identity(request):
        return RedirectResponse('/account', status_code=303)
    # Use the shipped scene without loading the Godot engine or game assets.
    source = (Path(__file__).resolve().parents[1] / 'web' / 'index.html').read_text(encoding='utf-8')
    source = re.split(r'<script src="[^"]+"></script><script>', source, maxsplit=1)[0]
    source = source.replace('Connecting…', 'Your realm awaits').replace('<span id="amount">—</span>', '')
    source = re.sub(r'<progress[^>]*></progress>', '', source)
    source += '</body></html>'
    return HTMLResponse(source, headers={'Cache-Control':'no-store','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; frame-ancestors 'self'"})
